import { component$, isDev, useVisibleTask$ } from "@builder.io/qwik";
import { QwikCityProvider, RouterOutlet } from "@builder.io/qwik-city";
import { RouterHead } from "./components/router-head/router-head";
import { ConvexProvider } from "./utils/convex-context";
import { AuthProvider } from "./utils/auth-context";
import { PostHogProvider } from "./utils/posthog-context";
import { installLixAuthInterceptor } from "./utils/lix-auth";
import { GlobalConnectivityBanner } from "./components/ui/global-connectivity-banner";
import { GlobalSpeechPlayer } from "./components/ui/global-speech-player";
import {
  THEME_BOOTSTRAP_SCRIPT,
  applyTheme,
  readThemePreference,
} from "./utils/theme";

import "./global.css";

export default component$(() => {
  const convexUrl = (import.meta.env.PUBLIC_CONVEX_URL ??
    import.meta.env.VITE_CONVEX_URL) as string | undefined;

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    installLixAuthInterceptor();

    // The bootstrap script resolves "System" once, at load. Keep following the
    // OS afterwards, so flipping the machine to dark at dusk re-inks the room
    // without a reload. Explicit presets are left alone.
    const query = window.matchMedia("(prefers-color-scheme: dark)");
    const sync = () => {
      const preference = readThemePreference();
      if (preference.preset !== "system") return;
      applyTheme(preference, document.documentElement, query.matches);
    };
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  });

  return (
    <QwikCityProvider>
      <head>
        <meta charset="utf-8" />
        {/*
          Stamps the writer's palette onto <html> before the first paint.
          It has to be an inline script rather than a component: Qwik
          server-renders the document, so any QRL resumes long after the
          browser has already painted the default cream — which is exactly
          the flash this avoids. The source lives in `utils/theme.ts` so it
          cannot drift from `applyTheme`.
        */}
        <script
          data-theme-bootstrap
          dangerouslySetInnerHTML={THEME_BOOTSTRAP_SCRIPT}
        />
        {!isDev && (
          <link
            rel="manifest"
            href={`${import.meta.env.BASE_URL}manifest.json`}
          />
        )}
        {/* Editorial type stack — Fraunces (display), Lora (body), DM Sans (UI), Special Elite (typewriter) */}
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link
          rel="preconnect"
          href="https://fonts.gstatic.com"
          crossOrigin="anonymous"
        />
        <link
          rel="stylesheet"
          href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Special+Elite&display=swap"
        />
        <RouterHead />
      </head>
      <body lang="en">
        <GlobalConnectivityBanner />
        <ConvexProvider url={convexUrl}>
          <AuthProvider>
            <PostHogProvider>
              <RouterOutlet />
              <GlobalSpeechPlayer />
            </PostHogProvider>
          </AuthProvider>
        </ConvexProvider>
      </body>
    </QwikCityProvider>
  );
});
import {
  $,
  component$,
  useStore,
  useVisibleTask$,
  type NoSerialize,
  type PropFunction,
} from "@builder.io/qwik";
import type { Editor } from "@tiptap/core";
import {
  checkGrammar,
  isEnglishLanguage,
  scalarOffsetToCodeUnit,
  type GrammarIssue,
} from "../../utils/grammar";

interface GrammarPanelProps {
  editor: NoSerialize<Editor> | null;
  readOnly?: boolean;
  onClose$: PropFunction<() => void>;
}

interface LocatedGrammarIssue extends GrammarIssue {
  from: number;
  to: number;
}

interface GrammarPanelStore {
  status: "loading" | "ready" | "error";
  issues: LocatedGrammarIssue[];
  error: string;
  scan: number;
  unsupportedLanguage: boolean;
}

interface TextBlock {
  text: string;
  docStart: number;
}

function collectTextBlocks(editor: Editor): TextBlock[] {
  const blocks: TextBlock[] = [];
  editor.state.doc.descendants((node, pos) => {
    if (!node.isTextblock) return true;
    if (node.textContent.trim()) {
      blocks.push({ text: node.textContent, docStart: pos + 1 });
    }
    return false;
  });
  return blocks;
}

/** Compact, progressive grammar desk backed by Harper's local WASM worker. */
export const GrammarPanel = component$<GrammarPanelProps>((props) => {
  const store = useStore<GrammarPanelStore>({
    status: "loading",
    issues: [],
    error: "",
    scan: 0,
    unsupportedLanguage: false,
  });

  const scan = $(async () => {
    const editor = props.editor;
    if (!editor) return;
    const mine = ++store.scan;
    store.status = "loading";
    store.error = "";
    const language =
      editor.view.dom.closest("[lang]")?.getAttribute("lang") ?? "";
    store.unsupportedLanguage = !isEnglishLanguage(language);
    if (store.unsupportedLanguage) {
      store.issues = [];
      store.status = "ready";
      return;
    }
    try {
      const located: LocatedGrammarIssue[] = [];
      for (const block of collectTextBlocks(editor)) {
        const issues = await checkGrammar(block.text, language);
        for (const issue of issues) {
          located.push({
            ...issue,
            from:
              block.docStart + scalarOffsetToCodeUnit(block.text, issue.start),
            to: block.docStart + scalarOffsetToCodeUnit(block.text, issue.end),
          });
        }
      }
      if (mine !== store.scan) return;
      store.issues = located;
      store.status = "ready";
    } catch (error) {
      if (mine !== store.scan) return;
      store.status = "error";
      store.error =
        error instanceof Error
          ? error.message
          : "Harper could not check this draft.";
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const editor = props.editor;
    if (!editor) return;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const schedule = () => {
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => void scan(), 700);
    };
    editor.on("update", schedule);
    void scan();
    cleanup(() => {
      if (timer) clearTimeout(timer);
      editor.off("update", schedule);
      store.scan += 1;
    });
  });

  const visit = $((issue: LocatedGrammarIssue) => {
    props.editor
      ?.chain()
      .focus()
      .setTextSelection({ from: issue.from, to: issue.to })
      .run();
  });

  const apply = $((issue: LocatedGrammarIssue, replacement: string) => {
    const editor = props.editor;
    if (!editor || props.readOnly) return;
    editor
      .chain()
      .focus()
      .insertContentAt({ from: issue.from, to: issue.to }, replacement)
      .run();
  });

  return (
    <aside
      class="fixed bottom-16 right-4 top-20 flex w-[22rem] max-w-[calc(100vw-2rem)] flex-col overflow-hidden border border-[var(--color-paper-3)] bg-[var(--color-paper)]"
      style={{
        zIndex: "var(--z-dropdown)",
        borderRadius: "4px",
        boxShadow:
          "0 4px 8px color-mix(in srgb, var(--shade) 20%, transparent)",
      }}
      aria-label="Grammar suggestions"
    >
      <div class="flex items-center justify-between gap-3 border-b border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] px-3 py-2.5">
        <div>
          <p class="dept-label">Grammar desk</p>
          <p
            class="mt-0.5 text-[0.62rem] text-[var(--color-ink-muted)]"
            style={{ fontFamily: "var(--font-typewriter)" }}
          >
            Harper runs here in your browser.
          </p>
        </div>
        <div class="flex items-center gap-1">
          <button
            type="button"
            class="tool-btn"
            onClick$={scan}
            disabled={store.status === "loading"}
            aria-label="Check grammar again"
            title="Check grammar again"
          >
            ↻
          </button>
          <button
            type="button"
            class="tool-btn"
            onClick$={props.onClose$}
            aria-label="Close grammar desk"
          >
            ×
          </button>
        </div>
      </div>
import { component$, useStore, useVisibleTask$ } from "@builder.io/qwik";
import { useSpeechPlayer } from "../../utils/use-speech-player";
import {
  currentSpeechSourceOffset,
  currentSpeechText,
  resumeSpeech,
  seekSpeech,
  speechState,
} from "../../utils/speech";
import {
  buildSpeechTimeline,
  speechPositionAtProgress,
  speechProgressAtOffset,
  type SpeechTimeline,
} from "../../utils/speech-follow-along";

const SENTENCE_HIGHLIGHT = "twyne-speech-sentence";
const WORD_HIGHLIGHT = "twyne-speech-word";

interface SpeechTextSlice {
  node: Text;
  start: number;
  end: number;
}

interface SpeechTextMap {
  root: HTMLElement;
  domText: string;
  text: string;
  slices: SpeechTextSlice[];
  timeline: SpeechTimeline;
}

interface HighlightRegistryLike {
  set(name: string, highlight: unknown): void;
  delete(name: string): void;
}

type HighlightConstructor = new (...ranges: Range[]) => unknown;

function speechHighlightApi(): {
  registry: HighlightRegistryLike;
  Highlight: HighlightConstructor;
} | null {
  const registry = (CSS as unknown as { highlights?: HighlightRegistryLike })
    .highlights;
  const Highlight = (window as unknown as { Highlight?: HighlightConstructor })
    .Highlight;
  return registry && Highlight ? { registry, Highlight } : null;
}

function clearSpeechHighlights(): void {
  const api = speechHighlightApi();
  api?.registry.delete(WORD_HIGHLIGHT);
  api?.registry.delete(SENTENCE_HIGHLIGHT);
}

function buildSpeechTextMap(root: HTMLElement): SpeechTextMap {
  const slices: SpeechTextSlice[] = [];
  const parts: string[] = [];
  let length = 0;
  let previousBlock: Element | null = null;
  const blockTags = new Set([
    "ADDRESS",
    "ARTICLE",
    "ASIDE",
    "BLOCKQUOTE",
    "DIV",
    "FIGCAPTION",
    "H1",
    "H2",
    "H3",
    "H4",
    "H5",
    "H6",
    "LI",
    "P",
    "PRE",
    "SECTION",
  ]);
  const nearestBlock = (textNode: Text): Element => {
    let element: Element | null = textNode.parentElement;
    while (element && element !== root) {
      if (blockTags.has(element.tagName)) return element;
      element = element.parentElement;
    }
    return root;
  };
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = (node as Text).parentElement;
      if (
        !parent ||
        parent.closest(
          'button, input, select, textarea, script, style, [aria-hidden="true"], [data-speech-ignore]',
        )
      ) {
        return NodeFilter.FILTER_REJECT;
      }
      if (
        !(node as Text).data.trim() &&
        parent === root &&
        root.children.length
      ) {
        return NodeFilter.FILTER_REJECT;
      }
      return node.textContent?.length
        ? NodeFilter.FILTER_ACCEPT
        : NodeFilter.FILTER_REJECT;
    },
  });

  let node = walker.nextNode();
  while (node) {
    const textNode = node as Text;
    const value = textNode.data;
    const block = nearestBlock(textNode);
    if (
      previousBlock &&
      block !== previousBlock &&
      !block.contains(previousBlock) &&
      !previousBlock.contains(block)
    ) {
      parts.push("\n\n");
      length += 2;
    }
    slices.push({ node: textNode, start: length, end: length + value.length });
    parts.push(value);
    length += value.length;
    previousBlock = block;
    node = walker.nextNode();
  }

  const text = parts.join("");
  let timeline = buildSpeechTimeline(text);
  const spokenText = currentSpeechText();
  if (root.dataset.speechSource === "plain" && spokenText) {
    const requestedStart = currentSpeechSourceOffset();
    const start =
      requestedStart !== null &&
      text.slice(requestedStart, requestedStart + spokenText.length) ===
        spokenText
        ? requestedStart
        : text.indexOf(spokenText);
    if (start >= 0) {
      const spokenTimeline = buildSpeechTimeline(spokenText);
      timeline = {
        totalWeight: spokenTimeline.totalWeight,
        words: spokenTimeline.words.map((word) => ({
          ...word,
          start: word.start + start,
          end: word.end + start,
          sentenceStart: word.sentenceStart + start,
          sentenceEnd: word.sentenceEnd + start,
        })),
      };
    }
  }
  return {
    root,
    domText: root.textContent ?? "",
    text,
    slices,
    timeline,
  };
}

function textRange(
  map: SpeechTextMap,
  start: number,
  end: number,
): Range | null {
  if (!map.slices.length || end <= start) return null;
  const startSlice =
    map.slices.find((slice) => start >= slice.start && start <= slice.end) ??
    map.slices[0];
  const endSlice =
    map.slices.find((slice) => end >= slice.start && end <= slice.end) ??
    map.slices[map.slices.length - 1];
  const range = document.createRange();
  range.setStart(
    startSlice.node,
    Math.max(0, Math.min(start - startSlice.start, startSlice.node.length)),
  );
  range.setEnd(
    endSlice.node,
    Math.max(0, Math.min(end - endSlice.start, endSlice.node.length)),
  );
  return range;
}

function caretOffsetFromPoint(
  map: SpeechTextMap,
  x: number,
  y: number,
): number | null {
  const documentWithCaret = document as Document & {
    caretPositionFromPoint?: (
      clientX: number,
      clientY: number,
    ) => { offsetNode: Node; offset: number } | null;
    caretRangeFromPoint?: (clientX: number, clientY: number) => Range | null;
  };
  const position = documentWithCaret.caretPositionFromPoint?.(x, y);
  const fallback = position
    ? null
    : documentWithCaret.caretRangeFromPoint?.(x, y);
  const node = position?.offsetNode ?? fallback?.startContainer;
  const offset = position?.offset ?? fallback?.startOffset;
  if (
    !(node instanceof Text) ||
    offset === undefined ||
    !map.root.contains(node)
  ) {
    return null;
  }
  const slice = map.slices.find((candidate) => candidate.node === node);
  return slice ? slice.start + offset : null;
}

function findSpeechTarget(id: string): HTMLElement | null {
  const candidates = document.querySelectorAll<HTMLElement>(
    `[data-speech-id="${CSS.escape(id)}"]`,
  );
  return (
    Array.from(candidates).find(
      (candidate) => candidate.getClientRects().length > 0,
    ) ?? null
  );
}

function scrollRangeIntoView(range: Range, root: HTMLElement): void {
  const rect = range.getBoundingClientRect();
  if (!rect.height) return;

  let scrollParent: HTMLElement | null = root.parentElement;
  while (scrollParent) {
    const style = window.getComputedStyle(scrollParent);
    if (
      /(auto|scroll)/u.test(style.overflowY) &&
      scrollParent.scrollHeight > scrollParent.clientHeight
    ) {
      break;
    }
    scrollParent = scrollParent.parentElement;
  }

  const bounds = scrollParent?.getBoundingClientRect();
  const top = bounds?.top ?? 0;
  const bottom = bounds?.bottom ?? window.innerHeight;
  if (rect.top >= top + 48 && rect.bottom <= bottom - 72) return;

  const behavior = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ? "auto"
    : "smooth";
  const delta = rect.top - (top + (bottom - top) * 0.42);
  if (scrollParent) scrollParent.scrollBy({ top: delta, behavior });
  else window.scrollBy({ top: delta, behavior });
}

function formatClock(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds <= 0) return "0:00";
  const whole = Math.floor(seconds);
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

/** Persistent transport for every narration surface in the application. */
export const GlobalSpeechPlayer = component$(() => {
  const player = useSpeechPlayer();
  const local = useStore({ customVoice: "", customOpen: false });

  // The speech manager emits real audio time but providers do not return word
  // timestamps. Pair that time with the visible prose's approximate timeline,
  // then use the browser Highlight API so Markdown formatting stays intact.
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    let activeMap: SpeechTextMap | null = null;
    let activeId = "";
    let lastSentence = "";
    let pointerId: number | null = null;
    let pointerType = "";
    let pointerStart = { x: 0, y: 0 };
    let resumeAfterSeek = false;
    let didSeek = false;

    const clearActive = () => {
      if (activeMap) {
        delete activeMap.root.dataset.speechActive;
        activeMap.root.classList.remove("is-speech-seeking");
      }
      activeMap = null;
      activeId = "";
      lastSentence = "";
      clearSpeechHighlights();
    };

    const sync = () => {
      const snapshot = speechState();
      if (
        !snapshot.id ||
        snapshot.status === "idle" ||
        snapshot.status === "error"
      ) {
        clearActive();
        return;
      }

      if (
        snapshot.id !== activeId ||
        !activeMap?.root.isConnected ||
        activeMap.root.textContent !== activeMap.domText
      ) {
        clearActive();
        const root = findSpeechTarget(snapshot.id);
        if (!root) return;
        activeMap = buildSpeechTextMap(root);
        activeId = snapshot.id;
        root.dataset.speechActive = snapshot.status;
      } else {
        activeMap.root.dataset.speechActive = snapshot.status;
      }

      if (!activeMap || snapshot.duration <= 0) {
        clearSpeechHighlights();
        return;
      }
      const position = speechPositionAtProgress(
        activeMap.timeline,
        snapshot.currentTime / snapshot.duration,
      );
      const api = speechHighlightApi();
      if (!position || !api) return;

      const sentence = textRange(
        activeMap,
        position.sentenceStart,
        position.sentenceEnd,
      );
      const word = textRange(activeMap, position.wordStart, position.wordEnd);
      if (sentence) {
        api.registry.set(SENTENCE_HIGHLIGHT, new api.Highlight(sentence));
      }
      if (word) api.registry.set(WORD_HIGHLIGHT, new api.Highlight(word));

      const sentenceKey = `${activeId}:${position.sentenceStart}`;
      if (sentence && sentenceKey !== lastSentence && pointerId === null) {
        lastSentence = sentenceKey;
        scrollRangeIntoView(sentence, activeMap.root);
      }
    };

    const seekFromPoint = (x: number, y: number) => {
      const snapshot = speechState();
      if (
        !activeMap ||
        snapshot.id !== activeId ||
        snapshot.duration <= 0 ||
        (snapshot.status !== "playing" && snapshot.status !== "paused")
      ) {
        return;
      }
      const offset = caretOffsetFromPoint(activeMap, x, y);
      if (offset === null) return;
      const firstWord = activeMap.timeline.words[0];
      const lastWord = activeMap.timeline.words.at(-1);
      if (
        !firstWord ||
        !lastWord ||
        offset < firstWord.start ||
        offset > lastWord.end
      ) {
        return;
      }
      seekSpeech(
        speechProgressAtOffset(activeMap.timeline, offset) * snapshot.duration,
      );
      didSeek = true;
    };

    const onPointerDown = (event: PointerEvent) => {
      if (event.button !== 0 || pointerId !== null || !activeMap) return;
      const target = event.target instanceof Element ? event.target : null;
      const root = target?.closest<HTMLElement>("[data-speech-id]");
      if (
        root !== activeMap.root ||
        target?.closest("a, button, input, select, textarea")
      ) {
        return;
      }
      const snapshot = speechState();
      if (
        snapshot.id !== activeId ||
        snapshot.duration <= 0 ||
        (snapshot.status !== "playing" && snapshot.status !== "paused")
      ) {
        return;
      }

      pointerId = event.pointerId;
      pointerType = event.pointerType;
      pointerStart = { x: event.clientX, y: event.clientY };
      resumeAfterSeek = snapshot.status === "paused";
      didSeek = false;
      activeMap.root.classList.add("is-speech-seeking");
      if (pointerType !== "touch") {
        event.preventDefault();
        activeMap.root.setPointerCapture?.(event.pointerId);
        seekFromPoint(event.clientX, event.clientY);
      }
    };

    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerId !== pointerId || pointerType === "touch") return;
      event.preventDefault();
      seekFromPoint(event.clientX, event.clientY);
    };

    const finishPointer = (event: PointerEvent, cancelled = false) => {
      if (event.pointerId !== pointerId) return;
      if (
        !cancelled &&
        pointerType === "touch" &&
        Math.hypot(
          event.clientX - pointerStart.x,
          event.clientY - pointerStart.y,
        ) < 8
      ) {
        seekFromPoint(event.clientX, event.clientY);
      }
      activeMap?.root.classList.remove("is-speech-seeking");
      if (resumeAfterSeek && didSeek) resumeSpeech();
      pointerId = null;
      pointerType = "";
      resumeAfterSeek = false;
      didSeek = false;
      sync();
    };
    const onPointerCancel = (event: PointerEvent) => finishPointer(event, true);

    window.addEventListener("twyne:speech", sync);
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("pointermove", onPointerMove);
    document.addEventListener("pointerup", finishPointer);
    document.addEventListener("pointercancel", onPointerCancel);
    sync();

    cleanup(() => {
      clearActive();
      window.removeEventListener("twyne:speech", sync);
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("pointermove", onPointerMove);
      document.removeEventListener("pointerup", finishPointer);
      document.removeEventListener("pointercancel", onPointerCancel);
    });
  });

  if (player.state.status === "idle") return null;

  const busy = player.state.status === "loading";
  const paused = player.state.status === "paused";
  const playing = player.state.status === "playing";
  const canGoBack = player.state.queueIndex > 0 || player.state.currentTime > 0;
  const canGoNext = player.state.queueIndex < player.state.queueLength - 1;
  const progressMax = Math.max(player.state.duration, 0);

  return (
    <aside
      class="fixed bottom-3 left-1/2 w-[min(44rem,calc(100vw-1rem))] -translate-x-1/2 border border-[var(--color-paper-3)] bg-[var(--color-paper)]"
      style={{
        zIndex: "var(--z-overlay)",
        borderRadius: "4px",
        boxShadow:
          "0 4px 8px color-mix(in srgb, var(--shade) 24%, transparent)",
      }}
      aria-label="Global narration player"
    >
      <div class="flex min-w-0 flex-wrap items-center gap-2 px-2.5 py-2 sm:gap-3 sm:px-3">
        <div class="min-w-0 flex-1">
          <div class="flex min-w-0 items-baseline gap-2">
            <p
              class="truncate text-xs font-semibold text-[var(--color-ink)]"
              style={{ fontFamily: "var(--font-display)" }}
            >
              {player.state.label || "Read aloud"}
            </p>
            {player.state.queueLength > 1 && (
              <span
                class="shrink-0 text-[0.6rem] text-[var(--color-ink-muted)]"
                style={{ fontFamily: "var(--font-typewriter)" }}
              >
                {player.state.queueIndex + 1} of {player.state.queueLength}
              </span>
            )}
          </div>
          <p
            class="truncate text-[0.6rem] text-[var(--color-ink-muted)]"
            style={{ fontFamily: "var(--font-typewriter)" }}
          >
            {player.state.status === "error"
              ? player.state.error?.message || "Narration failed"
              : busy
                ? "Preparing voice…"
                : `${player.voiceMenu.provider || player.state.provider || "Voice"} · ${player.voiceMenu.model || player.state.model || "narration"}`}
          </p>
        </div>

        <div class="flex shrink-0 items-center gap-1">
          <button
            type="button"
            class="tool-btn"
            aria-label="Previous passage"
            title="Previous passage"
