import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";

const settingsSource = readFileSync(
  new URL("../routes/settings/index.tsx", import.meta.url),
  "utf8",
);

describe("settings dropdown wiring", () => {
  test("uses the site dropdown for every settings choice", () => {
    expect(settingsSource).not.toContain("<select");
    expect(settingsSource).not.toContain("<option");
    expect(settingsSource.match(/<SiteSelect/g)?.length).toBe(10);
  });

  test("keeps model-derived reasoning choices on the site dropdown", () => {
    expect(settingsSource).toContain("thinkingModels.flatMap");
    expect(settingsSource).toContain("option.values.filter");
    expect(settingsSource).toContain("ariaLabel={label}");
  });
});
import { describe, expect, test } from "bun:test";
import {
  buildSpeechTimeline,
  speechPositionAtProgress,
  speechProgressAtOffset,
} from "./speech-follow-along";

describe("speech follow-along timeline", () => {
  test("keeps apostrophes and hyphens inside words", () => {
    const timeline = buildSpeechTimeline("Don't re-read the well-made line.");

    expect(timeline.words.map((word) => word.text)).toEqual([
      "Don't",
      "re-read",
      "the",
      "well-made",
      "line",
    ]);
  });

  test("groups the active word into its sentence", () => {
    const text = "First sentence. Second sentence, still here! Final thought.";
    const timeline = buildSpeechTimeline(text);
    const second = timeline.words.find((word) => word.text === "still");

    expect(second).toBeDefined();
    const middleOfSecond =
      ((second?.weightStart ?? 0) + (second?.weightEnd ?? 0)) /
      2 /
      timeline.totalWeight;
    const position = speechPositionAtProgress(timeline, middleOfSecond);

    expect(text.slice(position?.wordStart, position?.wordEnd)).toBe("still");
    expect(text.slice(position?.sentenceStart, position?.sentenceEnd)).toBe(
      "Second sentence, still here",
    );
  });

  test("maps a chosen word back to clip progress", () => {
    const text = "Alpha beta, gamma. Delta epsilon.";
    const timeline = buildSpeechTimeline(text);
    const deltaOffset = text.indexOf("Delta") + 2;
    const progress = speechProgressAtOffset(timeline, deltaOffset);
    const position = speechPositionAtProgress(timeline, progress);

    expect(progress).toBeGreaterThan(0);
    expect(progress).toBeLessThan(1);
    expect(text.slice(position?.wordStart, position?.wordEnd)).toBe("Delta");
  });

  test("clamps offsets and progress at both ends", () => {
    const timeline = buildSpeechTimeline("One two three");

    expect(speechProgressAtOffset(timeline, -10)).toBe(0);
    expect(speechProgressAtOffset(timeline, 10_000)).toBe(1);
    expect(speechPositionAtProgress(timeline, -1)?.wordStart).toBe(0);
    expect(speechPositionAtProgress(timeline, 2)?.wordEnd).toBe(13);
  });
});

import { $, useStore, useVisibleTask$, type QRL } from "@builder.io/qwik";
import {
  currentSpeechVoiceMenu,
  nextSpeech,
  previousSpeech,
  restartSpeechWithVoice,
  retrySpeech,
  seekSpeech,
  speechState,
  stopSpeech,
  togglePauseSpeech,
  type SpeechState,
  type SpeechVoiceMenu,
} from "./speech";

export interface SpeechPlayerHook {
  state: SpeechState;
  voiceMenu: SpeechVoiceMenu;
  toggle$: QRL<() => void>;
  previous$: QRL<() => void>;
  next$: QRL<() => void>;
  stop$: QRL<() => void>;
  seek$: QRL<(seconds: number) => void>;
  changeVoice$: QRL<(voice: string) => Promise<void>>;
  retry$: QRL<() => Promise<void>>;
}

const EMPTY_VOICE_MENU: SpeechVoiceMenu = {
  provider: "",
  model: "",
  selected: "",
  options: [],
  allowsCustom: false,
};

/**
 * Reactive Qwik interface over the application-wide speech manager.
 * Components use this hook instead of each binding their own audio element or
 * duplicating event cleanup.
 */
export function useSpeechPlayer(): SpeechPlayerHook {
  const state = useStore<SpeechState>(speechState());
  const voiceMenu = useStore<SpeechVoiceMenu>({ ...EMPTY_VOICE_MENU });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    let voiceKey = "";
    let menuGeneration = 0;

    const sync = () => {
      const snapshot = speechState();
      Object.assign(state, snapshot);

      const nextKey = `${snapshot.id ?? ""}:${snapshot.status}:${snapshot.voice ?? ""}`;
      if (!snapshot.id || nextKey === voiceKey) return;
      voiceKey = nextKey;
      const mine = ++menuGeneration;
      void currentSpeechVoiceMenu().then((menu) => {
        if (mine !== menuGeneration || !menu) return;
        Object.assign(voiceMenu, menu);
      });
    };

    window.addEventListener("twyne:speech", sync);
    sync();
    cleanup(() => {
      menuGeneration += 1;
      window.removeEventListener("twyne:speech", sync);
    });
  });

  return {
    state,
    voiceMenu,
    toggle$: $(() => togglePauseSpeech()),
    previous$: $(() => previousSpeech()),
    next$: $(() => nextSpeech()),
    stop$: $(() => stopSpeech()),
    seek$: $((seconds: number) => seekSpeech(seconds)),
    changeVoice$: $(async (voice: string) => restartSpeechWithVoice(voice)),
    retry$: $(async () => retrySpeech()),
  };
}
